-- All 10 migrations run in ONE transaction: if anything fails, NOTHING is changed.
-- It refuses to run before the backup (step 1), and refuses to run twice.
-- It records each migration in Supabase's migration history (supabase_migrations.schema_migrations).
-- What you should see: "Success. No rows returned".
-- An error → nothing was changed. Copy the whole error and send it to Claude. Don't run it again.
-- Generated by scripts/build-sql-editor.mjs from supabase/migrations — don't edit by hand.

begin;

do $$
declare
  applied boolean := false;
begin
  -- (dynamic: the history table doesn't exist yet on a first run)
  if to_regclass('supabase_migrations.schema_migrations') is not null then
    execute 'select exists (select 1 from supabase_migrations.schema_migrations where version = $1)' into applied using '20261016001000';
  end if;
  if applied then
    raise exception 'These migrations are already applied. Nothing was changed.';
  end if;
  if not exists (select 1 from pg_namespace where nspname = 'backup_phase0') then
    raise exception 'Run 1-backup.sql first. Nothing was changed.';
  end if;
end $$;

-- ===== 20261016000100_baseline.sql

-- 20261016000100 baseline: today's production schema, captured from the repo's legacy
-- SQL (supabase/legacy: schema.sql + 002 + 004 + 005). Every statement is idempotent,
-- so it is safe on the existing production database (where all of it already ran) and
-- rebuilds a fresh database from scratch. No data changes here.
-- Rollback: nothing to undo on production (it changes nothing that exists). On a fresh
-- database, drop the schema.


-- ================================================================ legacy schema.sql
-- AI VA Agency: multi-tenant schema.
-- Every table carries business_id; one database serves many businesses, isolated by
-- business_id. A new business (any domain) = new rows, not new code.
-- Apply: Supabase dashboard -> SQL Editor -> paste this file -> Run. Then run seed.sql.

-- ---------------------------------------------------------------- businesses
create table if not exists public.businesses (
  id          uuid primary key default gen_random_uuid(),
  name        text not null,
  -- per-business flexible config: hours, services[], rules, emergency_line, timezone
  config      jsonb not null default '{}'::jsonb,
  created_at  timestamptz not null default now()
);

-- ---------------------------------------------------------------- contacts
-- A person, deduped per business by email (emails are stored lower-cased).
create table if not exists public.contacts (
  id           uuid primary key default gen_random_uuid(),
  business_id  uuid not null references public.businesses(id) on delete cascade,
  name         text,
  email        text,
  phone        text,
  created_at   timestamptz not null default now(),
  constraint contacts_business_email_key unique (business_id, email)
);

-- ---------------------------------------------------------------- conversations
create table if not exists public.conversations (
  id           uuid primary key default gen_random_uuid(),
  business_id  uuid not null references public.businesses(id) on delete cascade,
  contact_id   uuid references public.contacts(id) on delete set null,
  channel      text not null,
  status       text not null default 'open',
  started_at   timestamptz not null default now()
);
create index if not exists conversations_business_idx on public.conversations (business_id);
create index if not exists conversations_contact_idx on public.conversations (contact_id);

-- ---------------------------------------------------------------- messages
create table if not exists public.messages (
  id               uuid primary key default gen_random_uuid(),
  business_id      uuid not null references public.businesses(id) on delete cascade,
  conversation_id  uuid not null references public.conversations(id) on delete cascade,
  role             text not null check (role in ('user', 'agent')),
  -- which agent spoke; null for user messages and for the safety-net emergency reply
  agent            text check (agent in ('receptionist', 'booking', 'sales', 'support')),
  content          text not null,
  created_at       timestamptz not null default now()
);
create index if not exists messages_conversation_idx on public.messages (conversation_id, created_at);
create index if not exists messages_business_idx on public.messages (business_id);

-- ---------------------------------------------------------------- bookings
create table if not exists public.bookings (
  id                 uuid primary key default gen_random_uuid(),
  business_id        uuid not null references public.businesses(id) on delete cascade,
  contact_id         uuid references public.contacts(id) on delete set null,
  conversation_id    uuid references public.conversations(id) on delete set null,
  service            text not null,
  slot_start         timestamptz not null,
  slot_end           timestamptz not null,
  calcom_booking_id  text not null, -- Cal.com booking uid (v2 addresses bookings by uid)
  status             text not null,
  created_at         timestamptz not null default now()
);
create index if not exists bookings_business_idx on public.bookings (business_id);
create index if not exists bookings_contact_idx on public.bookings (contact_id, slot_start);

-- ---------------------------------------------------------------- escalations
create table if not exists public.escalations (
  id               uuid primary key default gen_random_uuid(),
  business_id      uuid not null references public.businesses(id) on delete cascade,
  contact_id       uuid references public.contacts(id) on delete set null,
  conversation_id  uuid references public.conversations(id) on delete set null,
  reason           text not null,
  status           text not null default 'open',
  created_at       timestamptz not null default now()
);
create index if not exists escalations_business_idx on public.escalations (business_id);

-- ---------------------------------------------------------------- access
-- Row Level Security on, with no policies: the public anon/publishable key can read or
-- write nothing. The app talks to these tables only from the server with the service
-- role key, which bypasses RLS.
alter table public.businesses    enable row level security;
alter table public.contacts      enable row level security;
alter table public.conversations enable row level security;
alter table public.messages      enable row level security;
alter table public.bookings      enable row level security;
alter table public.escalations   enable row level security;

-- ================================================================ legacy 002
-- 002: allow the Sales and Support agents in messages.agent.
-- Apply: Supabase dashboard -> SQL Editor -> paste -> Run (after schema.sql / seed.sql).
-- Postgres names an inline column check "<table>_<column>_check".
alter table public.messages drop constraint if exists messages_agent_check;
alter table public.messages
  add constraint messages_agent_check
  check (agent in ('receptionist', 'booking', 'sales', 'support'));

-- ================================================================ legacy 004 (schema part)
-- 004: owner setup, business type packs, booking requests, Today screen.
-- Apply: Supabase dashboard -> SQL Editor -> paste this whole file -> Run.
-- Safe to re-run (IF NOT EXISTS / OR REPLACE / DROP ... IF EXISTS).
-- New tables follow the existing rule: RLS on, no policies (server-only access with the
-- service role key, which bypasses RLS).

-- ---------------------------------------------------------------- 5.1 businesses
alter table public.businesses
  add column if not exists vertical text check (vertical in ('dental', 'salon', 'aircon')),
  add column if not exists booking_slug text unique,
  add column if not exists owner_mobile text,
  add column if not exists setup_completed_at timestamptz,
  add column if not exists calendar_mode text not null default 'requests'
    check (calendar_mode in ('calcom', 'requests')),
  add column if not exists last_seen_at timestamptz;

-- ---------------------------------------------------------------- 5.2 services
create table if not exists public.services (
  id                uuid primary key default gen_random_uuid(),
  business_id       uuid not null references public.businesses(id) on delete cascade,
  name              text not null,
  -- per unit for pricing_type = 'per_unit'
  duration_minutes  int not null check (duration_minutes > 0),
  -- null = the team confirms the price
  price_php         numeric(10, 2),
  pricing_type      text not null default 'fixed'
    check (pricing_type in ('fixed', 'by_hair_length', 'per_unit')),
  -- by_hair_length: {"short":{"price_php":n|null,"duration_minutes":n},"shoulder":{...},"long":{...}}
  variants          jsonb,
  active            boolean not null default true,
  sort_order        int not null default 0,
  created_at        timestamptz not null default now()
);
create index if not exists services_business_idx on public.services (business_id);

-- ---------------------------------------------------------------- 5.3 staff
create table if not exists public.staff (
  id           uuid primary key default gen_random_uuid(),
  business_id  uuid not null references public.businesses(id) on delete cascade,
  name         text not null,
  active       boolean not null default true,
  created_at   timestamptz not null default now()
);
create index if not exists staff_business_idx on public.staff (business_id);

-- ---------------------------------------------------------------- 5.4 staff_hours
-- Several rows on one weekday = split shifts (e.g. a lunch break). 0 = Sunday.
create table if not exists public.staff_hours (
  id           uuid primary key default gen_random_uuid(),
  business_id  uuid not null references public.businesses(id) on delete cascade,
  staff_id     uuid not null references public.staff(id) on delete cascade,
  weekday      smallint not null check (weekday between 0 and 6),
  start_time   time not null,
  end_time     time not null,
  check (end_time > start_time)
);
create index if not exists staff_hours_business_idx on public.staff_hours (business_id);
create index if not exists staff_hours_staff_idx on public.staff_hours (staff_id);

-- ---------------------------------------------------------------- 5.5 bookings
alter table public.bookings
  add column if not exists staff_id uuid references public.staff(id) on delete set null,
  add column if not exists details jsonb,
  add column if not exists requested_time_text text,
  add column if not exists customer_mobile text,
  add column if not exists decline_reason text;

-- Booking requests have no time (or Cal.com booking) until the owner confirms them.
alter table public.bookings alter column slot_start drop not null;
alter table public.bookings alter column slot_end drop not null;
alter table public.bookings alter column calcom_booking_id drop not null;
alter table public.bookings drop constraint if exists bookings_confirmed_has_slot;
alter table public.bookings
  add constraint bookings_confirmed_has_slot check (status <> 'confirmed' or slot_start is not null);
-- status has no check constraint, so 'requested' / 'confirmed' / 'declined' are allowed
-- alongside the existing Cal.com values.
create index if not exists bookings_staff_idx on public.bookings (staff_id, slot_start);

-- ---------------------------------------------------------------- 5.6 contacts
alter table public.contacts
  add column if not exists mobile text,
  add column if not exists consent_at timestamptz;
create unique index if not exists contacts_business_mobile_key
  on public.contacts (business_id, mobile) where mobile is not null;

-- ---------------------------------------------------------------- access
alter table public.services    enable row level security;
alter table public.staff       enable row level security;
alter table public.staff_hours enable row level security;


-- ================================================================ legacy 005
-- 005: more business types, brand color + public details, the tap-through booking
-- page (reference codes, preferred day / time of day, form vs chat source).
-- Apply: Supabase dashboard -> SQL Editor -> paste this whole file -> Run (after 004).
-- Safe to re-run.

-- ---------------------------------------------------------------- businesses
-- Business types are checked in code against the loaded packs (web/verticals/*.json),
-- so a new pack needs no database change.
alter table public.businesses drop constraint if exists businesses_vertical_check;

alter table public.businesses
  add column if not exists brand_color text,
  add column if not exists business_address text,
  add column if not exists public_contact text; -- phone number or Messenger link shown to customers

-- ---------------------------------------------------------------- bookings
alter table public.bookings
  add column if not exists reference_code text,
  add column if not exists preferred_day date,
  add column if not exists preferred_time_of_day text
    check (preferred_time_of_day in ('morning', 'afternoon', 'evening')),
  add column if not exists source text not null default 'chat'
    check (source in ('chat', 'form'));

create unique index if not exists bookings_business_reference_key
  on public.bookings (business_id, reference_code) where reference_code is not null;

-- ---------------------------------------------------------------- setup save
-- Same one-transaction save as 004, now also saving brand_color, business_address and
-- public_contact. The business type itself is checked against the packs by the server
-- action; here it must at least be a well-formed id.
create or replace function public.create_business_setup(p jsonb)
returns table (new_business_id uuid, new_slug text)
language plpgsql
as $$
declare
  v_id uuid;
  v_base text := coalesce(nullif(p->>'base_slug', ''), 'business');
  v_slug text := v_base;
  v_n int := 1;
  v_svc jsonb;
  v_staff jsonb;
  v_staff_id uuid;
  v_hour jsonb;
begin
  if coalesce(p->>'vertical', '') !~ '^[a-z][a-z0-9_]{1,40}$' then
    raise exception 'invalid business type';
  end if;

  while exists (select 1 from public.businesses b where b.booking_slug = v_slug) loop
    v_n := v_n + 1;
    v_slug := v_base || '-' || v_n;
  end loop;

  insert into public.businesses
    (name, vertical, booking_slug, owner_mobile, calendar_mode, setup_completed_at, config,
     brand_color, business_address, public_contact)
  values
    (p->>'name', p->>'vertical', v_slug, p->>'owner_mobile', 'requests', now(),
     coalesce(p->'config', '{}'::jsonb),
     nullif(p->>'brand_color', ''), nullif(p->>'business_address', ''), nullif(p->>'public_contact', ''))
  returning id into v_id;

  for v_svc in select value from jsonb_array_elements(coalesce(p->'services', '[]'::jsonb)) loop
    insert into public.services
      (business_id, name, duration_minutes, price_php, pricing_type, variants, active, sort_order)
    values (
      v_id,
      v_svc->>'name',
      (v_svc->>'duration_minutes')::int,
      (v_svc->>'price_php')::numeric,
      coalesce(v_svc->>'pricing_type', 'fixed'),
      case when jsonb_typeof(v_svc->'variants') = 'object' then v_svc->'variants' end,
      coalesce((v_svc->>'active')::boolean, true),
      coalesce((v_svc->>'sort_order')::int, 0)
    );
  end loop;

  for v_staff in select value from jsonb_array_elements(coalesce(p->'staff', '[]'::jsonb)) loop
    insert into public.staff (business_id, name)
    values (v_id, v_staff->>'name')
    returning id into v_staff_id;

    for v_hour in select value from jsonb_array_elements(coalesce(v_staff->'hours', '[]'::jsonb)) loop
      insert into public.staff_hours (business_id, staff_id, weekday, start_time, end_time)
      values (
        v_id,
        v_staff_id,
        (v_hour->>'weekday')::smallint,
        (v_hour->>'start_time')::time,
        (v_hour->>'end_time')::time
      );
    end loop;
  end loop;

  return query select v_id, v_slug;
end;
$$;

revoke execute on function public.create_business_setup(jsonb) from public, anon, authenticated;
grant execute on function public.create_business_setup(jsonb) to service_role;

-- ===== 20261016000200_memberships.sql

-- 20261016000200 memberships: who can access a business, and how (blueprint: Data model,
-- Security). Adds public.users (one row per Google account, with the builder flag),
-- memberships (owner | staff), and the security-definer helpers is_member() and
-- is_owner() that every row-level security policy uses.
-- Keeps all existing data (only new objects).
-- Rollback: drop trigger on_auth_user_created on auth.users; drop function
--   public.handle_new_user(), public.is_member(uuid), public.is_owner(uuid);
--   drop table public.memberships, public.users;

-- ---------------------------------------------------------------- users
create table if not exists public.users (
  id          uuid primary key references auth.users(id) on delete cascade,
  email       text,
  name        text,
  avatar_url  text,
  -- builder console access (blueprint: Surfaces). Only set by the platform, never by users.
  is_builder  boolean not null default false,
  created_at  timestamptz not null default now()
);
alter table public.users enable row level security;

-- Copy each new Google account into public.users.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.users (id, email, name, avatar_url)
  values (
    new.id,
    new.email,
    coalesce(new.raw_user_meta_data->>'full_name', new.raw_user_meta_data->>'name'),
    new.raw_user_meta_data->>'avatar_url'
  )
  on conflict (id) do nothing;
  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- Accounts that existed before this migration.
insert into public.users (id, email, name, avatar_url)
select u.id, u.email,
       coalesce(u.raw_user_meta_data->>'full_name', u.raw_user_meta_data->>'name'),
       u.raw_user_meta_data->>'avatar_url'
from auth.users u
on conflict (id) do nothing;

-- ---------------------------------------------------------------- memberships
create table if not exists public.memberships (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references auth.users(id) on delete cascade,
  business_id  uuid not null references public.businesses(id) on delete cascade,
  role         text not null check (role in ('owner', 'staff')),
  status       text not null default 'active' check (status in ('active', 'invited', 'removed')),
  created_at   timestamptz not null default now(),
  unique (user_id, business_id)
);
create index if not exists memberships_business_idx on public.memberships (business_id);
create index if not exists memberships_user_idx on public.memberships (user_id);
alter table public.memberships enable row level security;

-- ---------------------------------------------------------------- helpers
-- security definer so policies can check memberships without recursing into the
-- memberships table's own policies; search_path = '' so nothing can be shadowed.
create or replace function public.is_member(target_business uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.memberships m
    where m.business_id = target_business
      and m.user_id = (select auth.uid())
      and m.status = 'active'
  );
$$;

create or replace function public.is_owner(target_business uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.memberships m
    where m.business_id = target_business
      and m.user_id = (select auth.uid())
      and m.status = 'active'
      and m.role = 'owner'
  );
$$;

revoke execute on function public.is_member(uuid) from public, anon;
revoke execute on function public.is_owner(uuid) from public, anon;
grant execute on function public.is_member(uuid) to authenticated, service_role;
grant execute on function public.is_owner(uuid) to authenticated, service_role;
revoke execute on function public.handle_new_user() from public, anon, authenticated;

-- ===== 20261016000300_rls_policies.sql

-- 20261016000300 row-level security policies, based on membership (blueprint: Security).
-- Every table with a business_id: members can read and write their own business's rows.
-- Owner-only writes: the business itself, its services, team (staff, hours) and members.
-- Staff (blueprint: Home, Inbox, Schedule, Customers) can work on customers,
-- conversations, messages, bookings and needs-you items. Policies apply to signed-in
-- users only; the public anon key gets nothing (customer actions use narrow functions).
-- The server's service-role key bypasses RLS (used only by trusted server jobs).
-- Keeps all existing data (policies only). Policies follow tables through later renames.
-- Rollback: drop the policies created here (each is named "<table>: …");
--   the tables keep RLS on with no policies (deny all), as before this migration.

-- ---------------------------------------------------------------- businesses
drop policy if exists "businesses: members read" on public.businesses;
create policy "businesses: members read" on public.businesses
  for select to authenticated using ((select public.is_member(id)));
drop policy if exists "businesses: owners update" on public.businesses;
create policy "businesses: owners update" on public.businesses
  for update to authenticated using ((select public.is_owner(id))) with check ((select public.is_owner(id)));
-- No insert/delete policies: new businesses are created by create_business_setup().

-- ---------------------------------------------------------------- memberships
drop policy if exists "memberships: read own or as owner" on public.memberships;
create policy "memberships: read own or as owner" on public.memberships
  for select to authenticated using (user_id = (select auth.uid()) or (select public.is_owner(business_id)));
drop policy if exists "memberships: owners insert" on public.memberships;
create policy "memberships: owners insert" on public.memberships
  for insert to authenticated with check ((select public.is_owner(business_id)));
drop policy if exists "memberships: owners update" on public.memberships;
create policy "memberships: owners update" on public.memberships
  for update to authenticated using ((select public.is_owner(business_id))) with check ((select public.is_owner(business_id)));
drop policy if exists "memberships: owners delete" on public.memberships;
create policy "memberships: owners delete" on public.memberships
  for delete to authenticated using ((select public.is_owner(business_id)));

-- ---------------------------------------------------------------- users
drop policy if exists "users: read own" on public.users;
create policy "users: read own" on public.users
  for select to authenticated using (id = (select auth.uid()));
drop policy if exists "users: update own" on public.users;
create policy "users: update own" on public.users
  for update to authenticated using (id = (select auth.uid())) with check (id = (select auth.uid()));
-- Users may change only their name and picture, never the builder flag.
revoke update on public.users from anon, authenticated;
grant update (name, avatar_url) on public.users to authenticated;
revoke insert, delete on public.users from anon, authenticated;

-- ---------------------------------------------------------------- member-writable tables
do $$
declare
  t text;
begin
  foreach t in array array['contacts', 'conversations', 'messages', 'bookings', 'escalations'] loop
    -- skip tables already renamed by a later migration (safe re-run)
    continue when to_regclass('public.' || t) is null;
    execute format('drop policy if exists "%1$s: members read" on public.%1$I', t);
    execute format('create policy "%1$s: members read" on public.%1$I for select to authenticated using ((select public.is_member(business_id)))', t);
    execute format('drop policy if exists "%1$s: members insert" on public.%1$I', t);
    execute format('create policy "%1$s: members insert" on public.%1$I for insert to authenticated with check ((select public.is_member(business_id)))', t);
    execute format('drop policy if exists "%1$s: members update" on public.%1$I', t);
    execute format('create policy "%1$s: members update" on public.%1$I for update to authenticated using ((select public.is_member(business_id))) with check ((select public.is_member(business_id)))', t);
    execute format('drop policy if exists "%1$s: members delete" on public.%1$I', t);
    execute format('create policy "%1$s: members delete" on public.%1$I for delete to authenticated using ((select public.is_member(business_id)))', t);
  end loop;
end $$;

-- ---------------------------------------------------------------- owner-writable tables
do $$
declare
  t text;
begin
  foreach t in array array['services', 'staff', 'staff_hours'] loop
    continue when to_regclass('public.' || t) is null;
    execute format('drop policy if exists "%1$s: members read" on public.%1$I', t);
    execute format('create policy "%1$s: members read" on public.%1$I for select to authenticated using ((select public.is_member(business_id)))', t);
    execute format('drop policy if exists "%1$s: owners insert" on public.%1$I', t);
    execute format('create policy "%1$s: owners insert" on public.%1$I for insert to authenticated with check ((select public.is_owner(business_id)))', t);
    execute format('drop policy if exists "%1$s: owners update" on public.%1$I', t);
    execute format('create policy "%1$s: owners update" on public.%1$I for update to authenticated using ((select public.is_owner(business_id))) with check ((select public.is_owner(business_id)))', t);
    execute format('drop policy if exists "%1$s: owners delete" on public.%1$I', t);
    execute format('create policy "%1$s: owners delete" on public.%1$I for delete to authenticated using ((select public.is_owner(business_id)))', t);
  end loop;
end $$;

-- ===== 20261016000400_customers_needs_you.sql

-- 20261016000400 blueprint names: contacts → customers, escalations → needs_you_items
-- (Glossary: "Customer", "Needs you"). Renames keep every row, foreign key and policy.
-- needs_you_items gets a type (emergency, question, refund, complaint, other), backfilled
-- from the reason text, a link to a booking, and statuses open → done.
-- Rollback: alter table public.needs_you_items rename to escalations; drop the type and
--   booking_id columns and the check constraints; update status 'done' → 'resolved';
--   alter table public.customers rename to contacts; rename each customer_id column back
--   to contact_id (conversations, bookings, escalations).

do $$
begin
  -- ------------------------------------------------------------ contacts → customers
  if to_regclass('public.contacts') is not null and to_regclass('public.customers') is null then
    alter table public.contacts rename to customers;
  end if;
  if exists (select 1 from pg_constraint where conname = 'contacts_business_email_key') then
    alter table public.customers rename constraint contacts_business_email_key to customers_business_email_key;
  end if;
  if to_regclass('public.contacts_business_mobile_key') is not null then
    alter index public.contacts_business_mobile_key rename to customers_business_mobile_key;
  end if;
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'conversations' and column_name = 'contact_id') then
    alter table public.conversations rename column contact_id to customer_id;
  end if;
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'bookings' and column_name = 'contact_id') then
    alter table public.bookings rename column contact_id to customer_id;
  end if;
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'escalations' and column_name = 'contact_id') then
    alter table public.escalations rename column contact_id to customer_id;
  end if;
  if to_regclass('public.conversations_contact_idx') is not null then
    alter index public.conversations_contact_idx rename to conversations_customer_idx;
  end if;
  if to_regclass('public.bookings_contact_idx') is not null then
    alter index public.bookings_contact_idx rename to bookings_customer_idx;
  end if;

  -- ------------------------------------------------------------ escalations → needs_you_items
  if to_regclass('public.escalations') is not null and to_regclass('public.needs_you_items') is null then
    alter table public.escalations rename to needs_you_items;
  end if;
  if to_regclass('public.escalations_business_idx') is not null then
    alter index public.escalations_business_idx rename to needs_you_items_business_idx;
  end if;
end $$;

-- Policy names follow the new table names (policies themselves moved with the tables).
do $$
declare
  p record;
begin
  for p in
    select tablename, policyname from pg_policies
    where schemaname = 'public' and (policyname like 'contacts:%' or policyname like 'escalations:%')
  loop
    execute format('alter policy %I on public.%I rename to %I', p.policyname, p.tablename,
      replace(replace(p.policyname, 'contacts:', 'customers:'), 'escalations:', 'needs_you_items:'));
  end loop;
end $$;

-- ---------------------------------------------------------------- needs-you type + booking link
alter table public.needs_you_items
  add column if not exists type text,
  add column if not exists booking_id uuid references public.bookings(id) on delete set null;

update public.needs_you_items set type = case
    when reason ilike 'Emergency words%' then 'emergency'
    when reason ilike '%refund%' then 'refund'
    when reason ilike '%complain%' then 'complaint'
    else 'other'
  end
where type is null;

alter table public.needs_you_items alter column type set default 'other';
alter table public.needs_you_items alter column type set not null;
alter table public.needs_you_items drop constraint if exists needs_you_items_type_check;
alter table public.needs_you_items
  add constraint needs_you_items_type_check check (type in ('emergency', 'question', 'refund', 'complaint', 'other'));

-- Statuses: Open → Done (blueprint: Core objects).
update public.needs_you_items set status = 'done' where status = 'resolved';
do $$
declare
  odd text;
begin
  select string_agg(distinct status, ', ') into odd from public.needs_you_items where status not in ('open', 'done');
  if odd is not null then
    raise exception 'needs_you_items has unexpected status values: %. Map them in this migration before running it.', odd;
  end if;
end $$;
alter table public.needs_you_items drop constraint if exists needs_you_items_status_check;
alter table public.needs_you_items add constraint needs_you_items_status_check check (status in ('open', 'done'));
create index if not exists needs_you_items_booking_idx on public.needs_you_items (booking_id);

-- ===== 20261016000500_messages_conversations.sql

-- 20261016000500 messages and conversations (blueprint: Data model).
-- messages.role: customer / agent / owner / system ('user' → 'customer'; the safety
-- net's emergency reply, stored as an agent message with no agent, → 'system').
-- conversations.taken_over_by: the owner or staff member replying instead of the AI.
-- Keeps every row.
-- Rollback: drop constraint messages_role_check; update role 'customer' → 'user' and
--   'system' → 'agent'; re-add check (role in ('user','agent'));
--   alter table public.conversations drop column taken_over_by;

alter table public.messages drop constraint if exists messages_role_check;
update public.messages set role = 'customer' where role = 'user';
update public.messages set role = 'system' where role = 'agent' and agent is null;
do $$
declare
  odd text;
begin
  select string_agg(distinct role, ', ') into odd from public.messages where role not in ('customer', 'agent', 'owner', 'system');
  if odd is not null then
    raise exception 'messages has unexpected role values: %. Map them in this migration before running it.', odd;
  end if;
end $$;
alter table public.messages add constraint messages_role_check check (role in ('customer', 'agent', 'owner', 'system'));

alter table public.conversations
  add column if not exists taken_over_by uuid references auth.users(id) on delete set null;

-- ===== 20261016000600_booking_status_ticket_token.sql

-- 20261016000600 bookings: one set of statuses and a private ticket token
-- (blueprint: Core objects, Security). Statuses are exactly requested, confirmed,
-- declined, cancelled, completed, no_show, expired. Cal.com's 'accepted' → confirmed.
-- Any other value stops this migration with its name, so nothing is relabelled by guess.
-- ticket_token: 64 random hex characters (two v4 UUIDs), unique, for every booking;
-- the reference code stays for display only.
-- Keeps every row.
-- Rollback: drop constraint bookings_status_check; drop index bookings_ticket_token_key;
--   alter table public.bookings drop column ticket_token;
--   (statuses: 'confirmed' rows that had a calcom_booking_id were 'accepted' before.)

update public.bookings set status = 'confirmed' where status = 'accepted';
update public.bookings set status = 'cancelled' where status in ('canceled', 'cancelled');
update public.bookings set status = 'declined' where status = 'rejected';
update public.bookings set status = 'requested' where status = 'pending';

do $$
declare
  odd text;
begin
  select string_agg(distinct status, ', ') into odd from public.bookings
  where status not in ('requested', 'confirmed', 'declined', 'cancelled', 'completed', 'no_show', 'expired');
  if odd is not null then
    raise exception 'bookings has unexpected status values: %. Decide how to map them, add the mapping to this migration, then run it again.', odd;
  end if;
end $$;

alter table public.bookings drop constraint if exists bookings_status_check;
alter table public.bookings add constraint bookings_status_check
  check (status in ('requested', 'confirmed', 'declined', 'cancelled', 'completed', 'no_show', 'expired'));

-- ---------------------------------------------------------------- ticket token
alter table public.bookings add column if not exists ticket_token text;
update public.bookings
  set ticket_token = replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '')
  where ticket_token is null;
alter table public.bookings
  alter column ticket_token set default replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
alter table public.bookings alter column ticket_token set not null;
create unique index if not exists bookings_ticket_token_key on public.bookings (ticket_token);
alter table public.bookings drop constraint if exists bookings_ticket_token_length;
alter table public.bookings add constraint bookings_ticket_token_length check (length(ticket_token) >= 32);

-- ===== 20261016000700_business_profile.sql

-- 20261016000700 business_profile: what customers and the AI team know about a business
-- (blueprint: Data model), 1:1 with businesses, filled from businesses.config.
-- Typed columns for the blueprint's fields; everything else from config moves into
-- business_profile.settings (jsonb, where structure varies by business type), so nothing
-- is lost. businesses gains timezone and onboarding_state. businesses.config is renamed
-- config_legacy and kept for one release as a rollback safety net (no code reads it).
-- create_business_setup now writes the profile and, for a signed-in user, the owner
-- membership in the same transaction.
-- Rollback: alter table public.businesses rename column config_legacy to config;
--   drop table public.business_profile; alter table public.businesses drop column
--   timezone, drop column onboarding_state; restore create_business_setup from
--   20261016000100_baseline.sql (legacy 005 version).

-- ---------------------------------------------------------------- table
create table if not exists public.business_profile (
  business_id        uuid primary key references public.businesses(id) on delete cascade,
  about              text,
  payment_methods    text[] not null default '{}',
  walk_ins           boolean,
  hmos               text[] not null default '{}',
  service_areas      text[] not null default '{}',
  emergency_message  text,
  approval_limits    jsonb not null default '{}'::jsonb,
  faqs               jsonb not null default '[]'::jsonb,
  -- everything else (hours, owner name, customer term, rules, extra charges, minimum,
  -- pack version, legacy Cal.com services, ...)
  settings           jsonb not null default '{}'::jsonb,
  updated_at         timestamptz not null default now()
);
alter table public.business_profile enable row level security;

alter table public.businesses
  add column if not exists timezone text not null default 'Asia/Manila',
  add column if not exists onboarding_state jsonb not null default '{}'::jsonb;

-- ---------------------------------------------------------------- config → profile
create or replace function public.jsonb_text_array(v jsonb)
returns text[]
language sql
immutable
set search_path = ''
as $$
  select coalesce(array(select jsonb_array_elements_text(case when jsonb_typeof(v) = 'array' then v else '[]'::jsonb end)), '{}')
$$;

-- The keys that get their own column; the rest of config becomes settings.
create or replace function public.profile_settings(c jsonb)
returns jsonb
language sql
immutable
set search_path = ''
as $$
  select coalesce(c, '{}'::jsonb)
    - 'about' - 'payment_methods' - 'walk_ins' - 'hmos' - 'service_areas'
    - 'emergency_instruction' - 'emergency_line' - 'approval_limits' - 'refund_approval_limit_php'
    - 'faqs' - 'timezone' - 'onboarding'
$$;

create or replace function public.profile_approval_limits(c jsonb)
returns jsonb
language sql
immutable
set search_path = ''
as $$
  select coalesce(case when jsonb_typeof(c->'approval_limits') = 'object' then c->'approval_limits' end, '{}'::jsonb)
    || case when c ? 'refund_approval_limit_php' then jsonb_build_object('refund_over', c->'refund_approval_limit_php') else '{}'::jsonb end
$$;

do $$
begin
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'businesses' and column_name = 'config') then
    insert into public.business_profile
      (business_id, about, payment_methods, walk_ins, hmos, service_areas, emergency_message, approval_limits, faqs, settings)
    select b.id,
           b.config->>'about',
           public.jsonb_text_array(b.config->'payment_methods'),
           (b.config->>'walk_ins')::boolean,
           public.jsonb_text_array(b.config->'hmos'),
           public.jsonb_text_array(b.config->'service_areas'),
           coalesce(b.config->>'emergency_instruction', b.config->>'emergency_line'),
           public.profile_approval_limits(b.config),
           coalesce(case when jsonb_typeof(b.config->'faqs') = 'array' then b.config->'faqs' end, '[]'::jsonb),
           public.profile_settings(b.config)
    from public.businesses b
    on conflict (business_id) do nothing;

    update public.businesses
      set timezone = coalesce(nullif(config->>'timezone', ''), 'Asia/Manila'),
          onboarding_state = coalesce(case when jsonb_typeof(config->'onboarding') = 'object' then config->'onboarding' end, '{}'::jsonb);

    alter table public.businesses rename column config to config_legacy;
  end if;
end $$;

-- Any business without a profile (none expected) gets an empty one.
insert into public.business_profile (business_id)
select id from public.businesses
on conflict (business_id) do nothing;

-- ---------------------------------------------------------------- access
drop policy if exists "business_profile: members read" on public.business_profile;
create policy "business_profile: members read" on public.business_profile
  for select to authenticated using ((select public.is_member(business_id)));
drop policy if exists "business_profile: owners insert" on public.business_profile;
create policy "business_profile: owners insert" on public.business_profile
  for insert to authenticated with check ((select public.is_owner(business_id)));
drop policy if exists "business_profile: owners update" on public.business_profile;
create policy "business_profile: owners update" on public.business_profile
  for update to authenticated using ((select public.is_owner(business_id))) with check ((select public.is_owner(business_id)));
drop policy if exists "business_profile: owners delete" on public.business_profile;
create policy "business_profile: owners delete" on public.business_profile
  for delete to authenticated using ((select public.is_owner(business_id)));

-- ---------------------------------------------------------------- setup save
-- One transaction: business, profile, services, team, hours, and (for a signed-in
-- user) their owner membership. Input as before: { name, vertical, base_slug,
-- owner_mobile, brand_color, business_address, public_contact, config, services, staff }.
-- security definer: businesses have no insert policy; this is the only way in.
create or replace function public.create_business_setup(p jsonb)
returns table (new_business_id uuid, new_slug text)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
  v_cfg jsonb := coalesce(p->'config', '{}'::jsonb);
  v_base text := coalesce(nullif(p->>'base_slug', ''), 'business');
  v_slug text := v_base;
  v_n int := 1;
  v_svc jsonb;
  v_staff jsonb;
  v_staff_id uuid;
  v_hour jsonb;
begin
  if coalesce(p->>'vertical', '') !~ '^[a-z][a-z0-9_]{1,40}$' then
    raise exception 'invalid business type';
  end if;

  while exists (select 1 from public.businesses b where b.booking_slug = v_slug) loop
    v_n := v_n + 1;
    v_slug := v_base || '-' || v_n;
  end loop;

  insert into public.businesses
    (name, vertical, booking_slug, owner_mobile, calendar_mode, setup_completed_at, timezone, onboarding_state,
     brand_color, business_address, public_contact)
  values
    (p->>'name', p->>'vertical', v_slug, p->>'owner_mobile', 'requests', now(),
     coalesce(nullif(v_cfg->>'timezone', ''), 'Asia/Manila'), '{}'::jsonb,
     nullif(p->>'brand_color', ''), nullif(p->>'business_address', ''), nullif(p->>'public_contact', ''))
  returning id into v_id;

  insert into public.business_profile
    (business_id, about, payment_methods, walk_ins, hmos, service_areas, emergency_message, approval_limits, faqs, settings)
  values (
    v_id,
    v_cfg->>'about',
    public.jsonb_text_array(v_cfg->'payment_methods'),
    (v_cfg->>'walk_ins')::boolean,
    public.jsonb_text_array(v_cfg->'hmos'),
    public.jsonb_text_array(v_cfg->'service_areas'),
    coalesce(v_cfg->>'emergency_instruction', v_cfg->>'emergency_line'),
    public.profile_approval_limits(v_cfg),
    coalesce(case when jsonb_typeof(v_cfg->'faqs') = 'array' then v_cfg->'faqs' end, '[]'::jsonb),
    public.profile_settings(v_cfg)
  );

  for v_svc in select value from jsonb_array_elements(coalesce(p->'services', '[]'::jsonb)) loop
    insert into public.services
      (business_id, name, duration_minutes, price_php, pricing_type, variants, active, sort_order)
    values (
      v_id,
      v_svc->>'name',
      (v_svc->>'duration_minutes')::int,
      (v_svc->>'price_php')::numeric,
      coalesce(v_svc->>'pricing_type', 'fixed'),
      case when jsonb_typeof(v_svc->'variants') = 'object' then v_svc->'variants' end,
      coalesce((v_svc->>'active')::boolean, true),
      coalesce((v_svc->>'sort_order')::int, 0)
    );
  end loop;

  for v_staff in select value from jsonb_array_elements(coalesce(p->'staff', '[]'::jsonb)) loop
    insert into public.staff (business_id, name)
    values (v_id, v_staff->>'name')
    returning id into v_staff_id;

    for v_hour in select value from jsonb_array_elements(coalesce(v_staff->'hours', '[]'::jsonb)) loop
      insert into public.staff_hours (business_id, staff_id, weekday, start_time, end_time)
      values (v_id, v_staff_id, (v_hour->>'weekday')::smallint, (v_hour->>'start_time')::time, (v_hour->>'end_time')::time);
    end loop;
  end loop;

  -- The signed-in person who finished onboarding owns the business.
  if (select auth.uid()) is not null then
    insert into public.memberships (user_id, business_id, role) values ((select auth.uid()), v_id, 'owner');
  end if;

  return query select v_id, v_slug;
end;
$$;

revoke execute on function public.create_business_setup(jsonb) from public, anon;
grant execute on function public.create_business_setup(jsonb) to authenticated, service_role;
revoke execute on function public.jsonb_text_array(jsonb) from public, anon;
revoke execute on function public.profile_settings(jsonb) from public, anon;
revoke execute on function public.profile_approval_limits(jsonb) from public, anon;

-- ===== 20261016000800_agents_and_logs.sql

-- 20261016000800 tables for later phases (blueprint: Data model), empty for now and
-- protected by row-level security, plus the five built-in agents for every business.
--   staff_services  who can do which service (owners edit; Team)
--   agents          built-in / template / custom agents (owners edit; staff read)
--   agent_runs      every time an agent acted (written by the server; members read)
--   notifications   every text or email sent (written by the server; members read)
--   audit_log       who changed what (written by the server; members read; append-only)
-- Built-in agents: receptionist, booking, sales, support (live) and admin_assistant
-- (paused: not built yet). A trigger gives every new business the same five.
-- Keeps all existing data (new objects only; idempotent seed).
-- Rollback: drop trigger businesses_seed_agents on public.businesses; drop function
--   public.seed_built_in_agents(); drop table public.audit_log, public.notifications,
--   public.agent_runs, public.agents, public.staff_services;

create table if not exists public.staff_services (
  id           uuid primary key default gen_random_uuid(),
  business_id  uuid not null references public.businesses(id) on delete cascade,
  staff_id     uuid not null references public.staff(id) on delete cascade,
  service_id   uuid not null references public.services(id) on delete cascade,
  created_at   timestamptz not null default now(),
  unique (staff_id, service_id)
);
create index if not exists staff_services_business_idx on public.staff_services (business_id);

create table if not exists public.agents (
  id               uuid primary key default gen_random_uuid(),
  business_id      uuid not null references public.businesses(id) on delete cascade,
  kind             text not null check (kind in ('built_in', 'template', 'custom')),
  key              text,            -- built-in agents: receptionist, booking, sales, support, admin_assistant
  name             text not null,
  job_text         text not null default '',
  trigger          jsonb,           -- custom agents (Phase 2)
  allowed_actions  jsonb not null default '[]'::jsonb,
  status           text not null default 'draft' check (status in ('draft', 'test', 'live', 'paused')),
  created_at       timestamptz not null default now(),
  unique (business_id, key)
);
create index if not exists agents_business_idx on public.agents (business_id);

create table if not exists public.agent_runs (
  id           uuid primary key default gen_random_uuid(),
  business_id  uuid not null references public.businesses(id) on delete cascade,
  agent_id     uuid references public.agents(id) on delete set null,
  input        jsonb,
  actions      jsonb not null default '[]'::jsonb,
  result       jsonb,
  tokens       int,
  created_at   timestamptz not null default now()
);
create index if not exists agent_runs_business_idx on public.agent_runs (business_id, created_at);

create table if not exists public.notifications (
  id           uuid primary key default gen_random_uuid(),
  business_id  uuid not null references public.businesses(id) on delete cascade,
  "to"         text not null,
  channel      text not null check (channel in ('sms', 'email')),
  template     text not null,
  status       text not null default 'queued' check (status in ('queued', 'sent', 'failed')),
  booking_id   uuid references public.bookings(id) on delete set null,
  created_at   timestamptz not null default now()
);
create index if not exists notifications_business_idx on public.notifications (business_id, created_at);

create table if not exists public.audit_log (
  id           uuid primary key default gen_random_uuid(),
  business_id  uuid not null references public.businesses(id) on delete cascade,
  actor_type   text not null check (actor_type in ('user', 'agent', 'system')),
  actor_id     text,
  action       text not null,
  before       jsonb,
  after        jsonb,
  created_at   timestamptz not null default now()
);
create index if not exists audit_log_business_idx on public.audit_log (business_id, created_at);

alter table public.staff_services enable row level security;
alter table public.agents enable row level security;
alter table public.agent_runs enable row level security;
alter table public.notifications enable row level security;
alter table public.audit_log enable row level security;

-- ---------------------------------------------------------------- policies
do $$
declare
  t text;
begin
  -- Owners edit; members read.
  foreach t in array array['staff_services', 'agents'] loop
    execute format('drop policy if exists "%1$s: members read" on public.%1$I', t);
    execute format('create policy "%1$s: members read" on public.%1$I for select to authenticated using ((select public.is_member(business_id)))', t);
    execute format('drop policy if exists "%1$s: owners insert" on public.%1$I', t);
    execute format('create policy "%1$s: owners insert" on public.%1$I for insert to authenticated with check ((select public.is_owner(business_id)))', t);
    execute format('drop policy if exists "%1$s: owners update" on public.%1$I', t);
    execute format('create policy "%1$s: owners update" on public.%1$I for update to authenticated using ((select public.is_owner(business_id))) with check ((select public.is_owner(business_id)))', t);
    execute format('drop policy if exists "%1$s: owners delete" on public.%1$I', t);
    execute format('create policy "%1$s: owners delete" on public.%1$I for delete to authenticated using ((select public.is_owner(business_id)))', t);
  end loop;
  -- Written only by trusted server jobs (service role); members read; nobody edits.
  foreach t in array array['agent_runs', 'notifications', 'audit_log'] loop
    execute format('drop policy if exists "%1$s: members read" on public.%1$I', t);
    execute format('create policy "%1$s: members read" on public.%1$I for select to authenticated using ((select public.is_member(business_id)))', t);
    execute format('drop policy if exists "%1$s: no direct insert" on public.%1$I', t);
    execute format('create policy "%1$s: no direct insert" on public.%1$I for insert to authenticated with check (false)', t);
    execute format('drop policy if exists "%1$s: no direct update" on public.%1$I', t);
    execute format('create policy "%1$s: no direct update" on public.%1$I for update to authenticated using (false)', t);
    execute format('drop policy if exists "%1$s: no direct delete" on public.%1$I', t);
    execute format('create policy "%1$s: no direct delete" on public.%1$I for delete to authenticated using (false)', t);
  end loop;
end $$;

-- ---------------------------------------------------------------- built-in agents
create or replace function public.seed_built_in_agents_for(target_business uuid)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into public.agents (business_id, kind, key, name, job_text, status) values
    (target_business, 'built_in', 'receptionist', 'Receptionist', 'Understand what the customer wants and route it.', 'live'),
    (target_business, 'built_in', 'booking', 'Booking', 'Turn a booking intent into a complete booking request.', 'live'),
    (target_business, 'built_in', 'sales', 'Sales', 'Answer new customers'' questions from the business''s own details.', 'live'),
    (target_business, 'built_in', 'support', 'Support', 'Help existing customers and pass anything else to the owner.', 'live'),
    (target_business, 'built_in', 'admin_assistant', 'Your assistant', 'Onboard the owner, then oversee the AI team.', 'paused')
  on conflict (business_id, key) do nothing;
$$;

create or replace function public.seed_built_in_agents()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.seed_built_in_agents_for(new.id);
  return new;
end;
$$;

drop trigger if exists businesses_seed_agents on public.businesses;
create trigger businesses_seed_agents
  after insert on public.businesses
  for each row execute function public.seed_built_in_agents();

select public.seed_built_in_agents_for(id) from public.businesses;

revoke execute on function public.seed_built_in_agents_for(uuid) from public, anon, authenticated;
revoke execute on function public.seed_built_in_agents() from public, anon, authenticated;

-- ===== 20261016000900_cruz_normal_business.sql

-- 20261016000900 Cruz Family Dental becomes a normal business (blueprint: Data model —
-- "one booking system for everyone"): built-in schedule (calendar_mode = requests),
-- Asia/Manila, ₱. Its legacy Cal.com services (business_profile.settings.services) become
-- rows in services (price blank = "price on request"); its owner (settings.owner_name)
-- becomes its one team member with the old opening hours (settings.hours); Cal.com is
-- kept only as a switched-off connection (settings.calcom). Bookings are untouched.
-- Does nothing if Cruz isn't in the database; safe to re-run.
-- Rollback: update businesses set calendar_mode = 'calcom', timezone = 'Asia/Singapore'
--   where id = '4eb77e14-4742-42d2-84e8-8a7d88785f67'; delete its staff and services rows
--   created here; restore settings.services from businesses.config_legacy->'services'.

do $$
declare
  cruz constant uuid := '4eb77e14-4742-42d2-84e8-8a7d88785f67';
  s jsonb;
  svc jsonb;
  v_staff uuid;
  day record;
begin
  select settings into s from public.business_profile where business_id = cruz;
  if not found then
    return; -- Cruz isn't in this database
  end if;

  update public.businesses set calendar_mode = 'requests', timezone = 'Asia/Manila' where id = cruz;

  -- Legacy Cal.com services → services rows; remember their Cal.com ids on the switched-off connection.
  if jsonb_typeof(s->'services') = 'array' then
    for svc in select value from jsonb_array_elements(s->'services') loop
      if not exists (select 1 from public.services where business_id = cruz and name = svc->>'name') then
        insert into public.services (business_id, name, duration_minutes, price_php, pricing_type, active, sort_order)
        values (cruz, svc->>'name', (svc->>'duration_minutes')::int, null, 'fixed', true,
                (select count(*) from public.services where business_id = cruz));
      end if;
    end loop;
    s := (s - 'services') || jsonb_build_object('calcom', jsonb_build_object(
      'enabled', false,
      'event_types', coalesce((select jsonb_object_agg(x->>'name', (x->>'calcom_event_type_id')::bigint)
                                 from jsonb_array_elements(s->'services') x), '{}'::jsonb)
    ));
    update public.business_profile set settings = s, updated_at = now() where business_id = cruz;
  end if;

  -- The owner as the one team member, with the old opening hours.
  if not exists (select 1 from public.staff where business_id = cruz) and coalesce(s->>'owner_name', '') <> '' then
    insert into public.staff (business_id, name) values (cruz, s->>'owner_name') returning id into v_staff;
    for day in
      select d.weekday, s->'hours'->>d.key as span
      from (values ('sun', 0), ('mon', 1), ('tue', 2), ('wed', 3), ('thu', 4), ('fri', 5), ('sat', 6)) as d(key, weekday)
    loop
      if day.span ~ '^\d{2}:\d{2}-\d{2}:\d{2}$' then
        insert into public.staff_hours (business_id, staff_id, weekday, start_time, end_time)
        values (cruz, v_staff, day.weekday, split_part(day.span, '-', 1)::time, split_part(day.span, '-', 2)::time);
      end if;
    end loop;
  end if;
end $$;

-- ===== 20261016001000_public_functions.sql

-- 20261016001000 customer (public) actions, as narrow functions scoped to ONE booking
-- link or ticket token (CLAUDE.md security rules; blueprint: Security). The public anon
-- key can call these and nothing else: it still has no table access at all.
--   public_storefront(link)            what a customer may see: no owner mobile, no internal settings
--   create_booking_request(link, req)  upserts the customer by mobile, creates a 'requested'
--                                      booking with a reference code and a private ticket token
--   public_ticket(token)               the ticket, by its 32+ character token only (never by code)
-- The server still validates every choice against the business's real options before
-- calling create_booking_request; this function enforces the basics on its own too.
-- Keeps all existing data (functions only).
-- Rollback: drop function public.public_storefront(text), public.create_booking_request(text, jsonb),
--   public.public_ticket(text);

-- ---------------------------------------------------------------- storefront
create or replace function public.public_storefront(p_link text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'business', jsonb_build_object(
      'id', b.id, 'name', b.name, 'vertical', b.vertical, 'booking_slug', b.booking_slug,
      'calendar_mode', b.calendar_mode, 'timezone', b.timezone, 'brand_color', b.brand_color,
      'business_address', b.business_address, 'public_contact', b.public_contact),
    'profile', jsonb_build_object(
      'about', p.about, 'payment_methods', to_jsonb(p.payment_methods), 'walk_ins', p.walk_ins,
      'hmos', to_jsonb(p.hmos), 'service_areas', to_jsonb(p.service_areas),
      'emergency_message', p.emergency_message, 'faqs', p.faqs,
      -- customer-relevant settings only (hours, rules, extra charges, minimum, ...)
      'settings', p.settings - 'calcom' - 'owner_name' - 'avg_job_value' - 'on_call'),
    'services', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', s.id, 'name', s.name, 'duration_minutes', s.duration_minutes, 'price_php', s.price_php,
        'pricing_type', s.pricing_type, 'variants', s.variants) order by s.sort_order, s.name)
      from public.services s where s.business_id = b.id and s.active), '[]'::jsonb),
    'staff', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', m.id, 'name', m.name,
        'hours', coalesce((select jsonb_agg(jsonb_build_object(
                    'weekday', h.weekday, 'start_time', to_char(h.start_time, 'HH24:MI'), 'end_time', to_char(h.end_time, 'HH24:MI'))
                    order by h.weekday, h.start_time)
                  from public.staff_hours h where h.staff_id = m.id), '[]'::jsonb)) order by m.created_at)
      from public.staff m where m.business_id = b.id and m.active), '[]'::jsonb)
  )
  from public.businesses b
  left join public.business_profile p on p.business_id = b.id
  where b.booking_slug = p_link and b.setup_completed_at is not null
$$;

-- ---------------------------------------------------------------- booking request
create or replace function public.create_booking_request(p_link text, req jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_business public.businesses%rowtype;
  v_mobile text := regexp_replace(coalesce(req->>'mobile', ''), '[\s-]', '', 'g');
  v_name text := left(btrim(coalesce(req->>'name', '')), 80);
  v_email text := nullif(lower(btrim(coalesce(req->>'email', ''))), '');
  v_customer uuid;
  v_conversation uuid;
  v_staff uuid;
  v_words text[];
  v_initials text;
  v_code text;
  v_token text;
  v_attempt int := 0;
begin
  select * into v_business from public.businesses where booking_slug = p_link and setup_completed_at is not null;
  if not found then
    raise exception 'This booking link isn''t active.';
  end if;
  if v_business.calendar_mode <> 'requests' then
    raise exception 'This business doesn''t take booking requests here.';
  end if;

  if v_mobile ~ '^\+639\d{9}$' then
    v_mobile := '0' || substr(v_mobile, 4);
  end if;
  if v_mobile !~ '^09\d{9}$' then
    raise exception 'Enter an 11-digit mobile number starting with 09.' using errcode = '22023', hint = 'mobile';
  end if;
  if v_name = '' then
    raise exception 'Enter your name.' using errcode = '22023';
  end if;
  if coalesce(req->>'service', '') = '' or not exists (
    select 1 from public.services where business_id = v_business.id and active and name = req->>'service'
  ) then
    raise exception 'Pick a service.' using errcode = '22023';
  end if;
  if coalesce(req->>'preferred_time_of_day', '') not in ('morning', 'afternoon', 'evening') then
    raise exception 'Pick a time of day.' using errcode = '22023';
  end if;

  -- Optional team member and conversation must belong to this business.
  if nullif(req->>'staff_id', '') is not null then
    select id into v_staff from public.staff where id = (req->>'staff_id')::uuid and business_id = v_business.id and active;
  end if;
  if nullif(req->>'conversation_id', '') is not null then
    select id into v_conversation from public.conversations where id = (req->>'conversation_id')::uuid and business_id = v_business.id;
  end if;

  -- One customer per mobile within the business (consent recorded once, when given).
  select id into v_customer from public.customers where business_id = v_business.id and mobile = v_mobile;
  if v_customer is null then
    insert into public.customers (business_id, name, mobile, phone, consent_at)
    values (v_business.id, v_name, v_mobile, v_mobile, case when (req->>'consent')::boolean then now() end)
    returning id into v_customer;
  else
    update public.customers
      set name = v_name,
          consent_at = coalesce(consent_at, case when (req->>'consent')::boolean then now() end)
      where id = v_customer;
  end if;
  if v_email is not null and v_email ~ '^[^\s@]+@[^\s@]+\.[^\s@]+$'
     and not exists (select 1 from public.customers where business_id = v_business.id and email = v_email) then
    update public.customers set email = v_email where id = v_customer and email is null;
  end if;
  if v_conversation is not null then
    update public.conversations set customer_id = v_customer where id = v_conversation;
  end if;

  -- Reference code (display only): two initials + 4 digits, unique per business.
  -- "Bella Hair Studio" → BH; one-word names use their first two letters ("Juans" → JU).
  v_words := array_remove(regexp_split_to_array(btrim(regexp_replace(v_business.name, '[^A-Za-z ]', '', 'g')), '\s+'), '');
  v_initials := upper(case
    when coalesce(array_length(v_words, 1), 0) >= 2 then left(v_words[1], 1) || left(v_words[2], 1)
    else left(coalesce(v_words[1], '') || 'KK', 2)
  end);

  loop
    v_attempt := v_attempt + 1;
    v_code := v_initials || '-' || lpad((floor(random() * 10000))::int::text, 4, '0');
    begin
      insert into public.bookings
        (business_id, customer_id, conversation_id, service, staff_id, details, requested_time_text,
         preferred_day, preferred_time_of_day, customer_mobile, status, source, reference_code)
      values
        (v_business.id, v_customer, v_conversation, req->>'service', v_staff,
         case when jsonb_typeof(req->'details') = 'object' then req->'details' end,
         left(coalesce(req->>'requested_time_text', ''), 200),
         nullif(req->>'preferred_day', '')::date, req->>'preferred_time_of_day', v_mobile,
         'requested', 'form', v_code)
      returning ticket_token into v_token;
      exit;
    exception when unique_violation then
      if v_attempt >= 8 then
        raise;
      end if;
    end;
  end loop;

  return jsonb_build_object('ticket_token', v_token, 'reference_code', v_code, 'customer_id', v_customer);
end;
$$;

-- ---------------------------------------------------------------- ticket
create or replace function public.public_ticket(p_token text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'reference_code', k.reference_code,
    'status', k.status,
    'service', k.service,
    'details', k.details,
    'requested_time_text', k.requested_time_text,
    'preferred_day', k.preferred_day,
    'preferred_time_of_day', k.preferred_time_of_day,
    'slot_start', k.slot_start,
    'slot_end', k.slot_end,
    'staff_id', k.staff_id,
    'team_member', (select m.name from public.staff m where m.id = k.staff_id),
    'first_name', split_part(btrim(coalesce(c.name, '')), ' ', 1),
    'business', jsonb_build_object(
      'name', b.name, 'booking_slug', b.booking_slug, 'brand_color', b.brand_color,
      'business_address', b.business_address, 'public_contact', b.public_contact, 'timezone', b.timezone)
  )
  from public.bookings k
  join public.businesses b on b.id = k.business_id
  left join public.customers c on c.id = k.customer_id
  where length(p_token) >= 32 and k.ticket_token = p_token
$$;

revoke execute on function public.public_storefront(text) from public;
revoke execute on function public.create_booking_request(text, jsonb) from public;
revoke execute on function public.public_ticket(text) from public;
grant execute on function public.public_storefront(text) to anon, authenticated, service_role;
grant execute on function public.create_booking_request(text, jsonb) to anon, authenticated, service_role;
grant execute on function public.public_ticket(text) to anon, authenticated, service_role;

